// Inter latin subset (WOFF1) — bundled to eliminate CDN dependency at cold start.
// Satori supports TTF/OTF/WOFF1 only; WOFF2 is NOT supported (parseBuffer crash).
// Regenerate: curl https://cdn.jsdelivr.net/npm/@fontsource/inter@4/files/inter-latin-{400,700}-normal.woff | base64 -w 0
const INTER_400_B64 = "";
const INTER_700_B64 = "";

function b64ToBuffer(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

export type FontEntry = { name: string; data: ArrayBuffer; weight: 400 | 700; style: "normal" };

export function getInterFonts(): FontEntry[] {
  return [
    { name: "Inter", data: b64ToBuffer(INTER_400_B64), weight: 400, style: "normal" },
    { name: "Inter", data: b64ToBuffer(INTER_700_B64), weight: 700, style: "normal" },
  ];
}
